import React, { useState, useEffect, useRef } from 'react';
import { SendIcon, MicIcon } from './Icons';
import { speakText, stopSpeaking } from '../utils/speechSynthesis';


export const ChatPanel = ({
  companion,
  messages,
  onSendMessage,
  startListening,
  stopListening,
  isListening,
  onStopAI,
}) => {

  // --------------------
  // STATES
  // --------------------
  const [newMessage, setNewMessage] = useState('');
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [currentAudio, setCurrentAudio] = useState(null);
  const chatEndRef = useRef(null);

  // --------------------
  // AUTO SCROLL
  // --------------------
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // --------------------
  // CLEANUP AUDIO ON UNMOUNT
  // --------------------
  useEffect(() => {
    return () => {
      if (currentAudio) {
        currentAudio.pause();
        currentAudio.src = '';
      }
      stopSpeaking();
    };
  }, [currentAudio]);

  // --------------------
  // AUDIO PLAY
  // --------------------
  const handlePlayMessage = (message) => {
    // Stop any currently playing audio
    handleStopAudio();

    if (message.audioUrl) {
      // ElevenLabs audio from backend
      const audio = new Audio(message.audioUrl);
      setCurrentAudio(audio);
      
      audio.play().catch(err => {
        console.error('Audio playback failed:', err);
        // Fallback to browser TTS if audio fails
        speakText(message.text || message.content);
      });

      audio.onended = () => {
        setIsSpeaking(false);
        setCurrentAudio(null);
      };

      setIsSpeaking(true);
    } else if (message.text || message.content) {
      // Fallback: Browser TTS
      speakText(message.text || message.content);
      setIsSpeaking(true);

      // Estimate duration
      const words = (message.text || message.content).split(' ').length;
      const duration = (words / 150) * 60 * 1000;

      setTimeout(() => setIsSpeaking(false), duration);
    }
  };

  const handleStopAudio = () => {
    // Stop browser speech synthesis
    stopSpeaking();
    
    // Stop ElevenLabs audio if playing
    if (currentAudio) {
      currentAudio.pause();
      currentAudio.currentTime = 0;
      setCurrentAudio(null);
    }
    
    setIsSpeaking(false);
  };

  // --------------------
  // SEND MESSAGE
  // --------------------
  const handleSendMessage = async (text) => {
  if (!text || !text.trim()) return;

  const timestamp = new Date().toISOString();
  const userMessage = {
    sender: 'user',
    text,
    timestamp,
    userId: userId, // Add userId
  };
  
  setMessages((prev) => [...prev, userMessage]);

  // ✅ Broadcast to all users in room via Socket.io
  socket.emit('chat-message', {
    roomId,
    userId,
    message: text,
    sender: 'user',
    timestamp,
  });

  try {
    const response = await sendChatMessage(
      text,
      companion.id,
      roomId,
      companion.subject || 'General',
      0
    );

    const aiMessage = {
      sender: 'ai',
      text: response.text || response.message || 'I received your message.',
      timestamp: new Date().toISOString(),
      source: response.source || 'gemini',
      audioUrl: response.audioUrl || null,
    };
    
    setMessages((prev) => [...prev, aiMessage]);
    
    // ✅ Broadcast AI response to all users
    socket.emit('chat-message', {
      roomId,
      userId: companion.id,
      message: aiMessage.text,
      sender: 'ai',
      timestamp: aiMessage.timestamp,
    });
    
    await playAudio(response.audioUrl, aiMessage.text);
  } catch (error) {
    console.error('Error sending message:', error);
  }
};


  // --------------------
  // VOICE BUTTON
  // --------------------
  const handleVoiceClick = () => {
    if (isListening) {
      stopListening();
    } else {
      startListening();
    }
  };

  // --------------------
  // UI
  // --------------------
  return (
    <div className="flex flex-col h-full bg-gray-900">

      {/* Header */}
      <div className="p-4 border-b border-gray-700 flex items-center justify-between">
        <h3 className="text-lg font-semibold text-white">
          Chat with {companion?.name || 'AI Tutor'}
        </h3>

        <button
          onClick={onStopAI}
          className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white text-sm rounded-lg"
        >
          Stop AI
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">

        {messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-400">
            <div className="text-6xl mb-4">🎓</div>
            <p>Start a conversation!</p>
          </div>
        ) : (
          messages.map((msg, idx) => (
            <div
              key={idx}
              className={`flex ${
                msg.sender === 'user' ? 'justify-end' : 'justify-start'
              }`}
            >
              <div
                className={`max-w-[75%] rounded-2xl px-4 py-2 ${
                  msg.sender === 'user'
                    ? 'bg-blue-600 text-white rounded-br-none'
                    : 'bg-gray-700 text-gray-100 rounded-bl-none'
                }`}
              >
                <p className="text-sm whitespace-pre-wrap">
                  {msg.text}
                </p>

                {/* PLAY BUTTON - Only for AI messages */}
                {msg.sender !== 'user' && (
                  <button
                    onClick={() =>
                      isSpeaking ? handleStopAudio() : handlePlayMessage(msg)
                    }
                    className="mt-2 text-xs text-blue-300 hover:underline"
                  >
                    {isSpeaking ? '⏸ Stop' : '▶ Play'}
                  </button>
                )}

                {msg.timestamp && (
                  <p className="text-xs opacity-70 mt-1">
                    {new Date(msg.timestamp).toLocaleTimeString([], {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </p>
                )}
              </div>
            </div>
          ))
        )}

        <div ref={chatEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 border-t border-gray-700">
        <form onSubmit={handleSendMessage} className="flex items-center gap-2">

          {/* Mic */}
          <button
            type="button"
            onClick={handleVoiceClick}
            className={`p-3 rounded-full ${
              isListening
                ? 'bg-blue-600 animate-pulse'
                : 'bg-gray-700 hover:bg-gray-600'
            }`}
          >
            <MicIcon className="w-5 h-5 text-white" />
          </button>

          {/* Text */}
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type your message..."
            className="flex-1 bg-gray-800 text-white rounded-full px-4 py-3 focus:outline-none"
          />

          {/* Send */}
          <button
            type="submit"
            disabled={!newMessage.trim()}
            className="p-3 bg-blue-600 rounded-full disabled:bg-gray-700"
          >
            <SendIcon className="w-5 h-5 text-white" />
          </button>

        </form>

        {isListening && (
          <p className="mt-2 text-center text-blue-400 animate-pulse">
            🎤 Listening...
          </p>
        )}
      </div>

    </div>
  );
};
